def relay_jumps(reach):
    if len(reach) == 0:
        return [-1, 0]
    jumps = []
    paths = []
    for i in range(len(reach)):
        jumps.append(-1)
        paths.append(0)
    jumps[0] = 0
    paths[0] = 1
    for i in range(len(reach)):
        if jumps[i] < 0:
            continue
        end = i + reach[i] + 1
        if end > len(reach):
            end = len(reach)
        for dest in range(i + 1, end):
            next_jump = jumps[i] + 1
            if jumps[dest] == -1 or next_jump < jumps[dest]:
                jumps[dest] = next_jump
                paths[dest] = paths[i]
            elif next_jump == jumps[dest]:
                paths[dest] += paths[i]
    return [jumps[-1], paths[-1]]

